export function pokemonAssetKey(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replaceAll("ß", "ss")
    .replaceAll("♀", "f")
    .replaceAll("♂", "m")
    .replace(/[^a-z0-9]+/g, "");
}

export function pokemonAssetId(value) {
  const key = pokemonAssetKey(value);
  return POKEMON_ASSET_IDS[key] || key;
}
